		if (f!!.sl >= 0.0) {
			return L!!.q * phi_l.v
		}
		if (f!!.sr <= 0.0) {
			return R!!.q * phi_r.v
		}
		var dsr: Double = f!!.sr - f!!.sl
		return ((((f!!.sr * L!!.q) * phi_l.v) - ((f!!.sl * R!!.q) * phi_r.v)) + ((f!!.sl * f!!.sr) * ((R!!.a * phi_r.v) - (L!!.a * phi_l.v)))) / dsr
	}

	@JvmStatic fun frictionUpdate(q: Double, u: Double, r: Double, dt: Double, rough_factor: Double): Double {
		if ((r <= 0.0) || (rough_factor <= 0.0)) {
			return q
		}
		var r43: Double = r * cpp.SysMath.Cbrt_d(r)
		var den: Double = 1.0 + (((dt * rough_factor) * cpp.SysMath.Abs_d(u)) / r43)
		return q / den
	}

	@JvmStatic fun localLossUpdate(q: Double, u: Double, k: Double, dx: Double, dt: Double): Double {
		if ((k <= 0.0) || (dx <= 0.0)) {
			return q
		}
		return q / (1.0 + (((dt * k) * cpp.SysMath.Abs_d(u)) / (2.0 * dx)))
	}

	@JvmStatic fun ufUpdate(q: Double, a: Double, u_old: Double, k3: Double, grad_term: Double, dt: Double): Double {
		if ((k3 <= 0.0) || (a <= 0.0)) {
			return q
		}
		var kUfVelFloor: Double = 0.01
		if ((cpp.SysMath.Abs_d(u_old) < kUfVelFloor) && (cpp.SysMath.Abs_d(q / a) < kUfVelFloor)) {
			return q
		}
		var qn: Double = (q + ((k3 * a) * u_old)) / (1.0 + k3)
		qn -= ((dt * k3) * a) * grad_term
		var dq: Double = qn - q
		var cap: Double = 0.5 * cpp.SysMath.Abs_d(q)
		if (cpp.SysMath.Abs_d(dq) > cap) {
			qn = q + (if (dq > 0.0) cap else -cap)
		}
		return qn
	}

	@JvmStatic fun tpaDepthOfArea(g: fv_FvGeometry?, a: Double): Double {
		return g!!.y_full + ((a - g!!.a_crown) / g!!.t_slot)
	}

	@JvmStatic fun tpaAreaOfDepth(g: fv_FvGeometry?, h: Double): Double {
		return g!!.a_crown + (g!!.t_slot * (h - g!!.y_full))
	}

	@JvmStatic fun tpaI1OfDepth(g: fv_FvGeometry?, h: Double): Double {
		return g!!.i1_crown + (g!!.a_crown * (h - g!!.y_full))
	}

	@JvmStatic fun faceCflDt(cfl: Double, dx: Double, u: Double, c: Double): Double {
		var s: Double = cpp.SysMath.Abs_d(u) + c
		return if (s > 1E-12) (cfl * dx) / s else 1E+30
	}

	@JvmStatic fun positivityScale(vol: Double, outflow: Double, dt: Double): Double {
		if ((outflow <= 0.0) || (dt <= 0.0)) {
			return 1.0
		}
		var take: Double = outflow * dt
		var avail: Double = if (vol > 0.0) vol else 0.0
		return if (take <= avail) 1.0 else avail / take
	}

}
